import {CATEGORIES,DEFAULT_PRODUCTS,DEFAULT_SETTINGS,money,itemKey,normaliseCart,cartLines,subtotal,addToCart,filterProducts,enquiryMessage,whatsappUrl,validateProduct,validImageUrl} from './core.js';
const $=(s,root=document)=>root.querySelector(s);const $$=(s,root=document)=>[...root.querySelectorAll(s)];const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeDecode=s=>{try{return decodeURIComponent(s);}catch{return '';}};
const ASSETS=new URL('./assets/',import.meta.url).pathname;
const DEMO_URL=new URL('./',import.meta.url).href.replace(/\/$/,'');
const icon=name=>`<i data-lucide="${name}" aria-hidden="true"></i>`;
let storageFailed=false;function read(key,fallback){try{const raw=localStorage.getItem('luxvibe.'+key);return raw===null?structuredClone(fallback):JSON.parse(raw);}catch{return structuredClone(fallback);}}
function persist(key,value){try{localStorage.setItem('luxvibe.'+key,JSON.stringify(value));return true;}catch{storageFailed=true;toast('Your browser could not save this change. It will last only for this visit.');return false;}}
let products=read('products',DEFAULT_PRODUCTS);if(!Array.isArray(products)||products.length>100)products=structuredClone(DEFAULT_PRODUCTS);products=products.filter(p=>{try{return typeof p.id==='string'&&validateProduct(p);}catch{return false;}});if(!products.length)products=structuredClone(DEFAULT_PRODUCTS);
let settings={...DEFAULT_SETTINGS,...read('settings',{})};let cart=normaliseCart(read('cart',[]),products);let wishlist=read('wishlist',[]);if(!Array.isArray(wishlist))wishlist=[];wishlist=wishlist.filter(id=>products.some(p=>p.id===id));let enquiries=read('enquiries',[]);if(!Array.isArray(enquiries))enquiries=[];
let ownerDemo=false;try{ownerDemo=sessionStorage.getItem('luxvibe.owner')==='yes';}catch{}
let selectedVariant='',selectedQuantity=1,galleryDetail=false;let filters={query:'',category:'All',max:10000,available:false,colour:'All',sort:'featured'};let editingProduct=null;let uploadedImage='';let enquiryCart=[];let route='';const modal=$('#modal');
function icons(){window.lucide?.createIcons({attrs:{'stroke-width':1.5}});}
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3500);}
function saveCart(){cart=normaliseCart(cart,products);persist('cart',cart);updateCounts();}
function count(){return cart.reduce((sum,p)=>sum+p.quantity,0);}
function updateCounts(){$$('.cart-count').forEach(el=>{el.textContent=count();el.hidden=!count();});$$('.wish-count').forEach(el=>{el.textContent=wishlist.length;el.hidden=!wishlist.length;});}
function image(p,extra='',eager=false){const value=p.image;const isData=validImageUrl(value)&&value.startsWith('data:');const src=isData?value:`${ASSETS}${value}-${value==='hero'?'960':'800'}.webp`;return `<img src="${esc(src)}" ${isData?'':`srcset="${ASSETS}${value}-${value==='hero'?'640':'400'}.webp ${value==='hero'?'640':'400'}w, ${src} ${value==='hero'?'960':'800'}w" sizes="(max-width:760px) 45vw, 30vw"`} alt="${esc(p.name)} in ${esc(p.colour)} — concept image" width="800" height="800" loading="${eager?'eager':'lazy'}" decoding="async" class="${value==='hero'?'hero-product ':''}${extra}">`;}
function productLink(p){return '#/product/'+encodeURIComponent(p.id);}
function card(p){return `<article class="product-card"><div class="product-visual"><a href="${productLink(p)}" aria-label="View ${esc(p.name)}">${image(p)}</a>${p.featured?'<span class="product-tag">THE EDIT</span>':''}<button class="heart ${wishlist.includes(p.id)?'saved':''}" data-action="wish" data-id="${esc(p.id)}" aria-label="${wishlist.includes(p.id)?'Remove':'Save'} ${esc(p.name)} ${wishlist.includes(p.id)?'from':'to'} wishlist" aria-pressed="${wishlist.includes(p.id)}">${icon('heart')}</button><a href="${productLink(p)}" class="quick-add">Explore this piece ${icon('arrow-up-right')}</a></div><div class="product-info"><div class="meta">${esc(p.category)} · Sample</div><h3><a href="${productLink(p)}">${esc(p.name)}</a></h3><div class="price"><span>${money(p.price)}</span><span class="swatch-dot" style="--colour:${/^#[a-f\d]{6}$/i.test(p.hex)?p.hex:'#591f2b'}" title="${esc(p.colour)}"></span></div></div></article>`;}
function header(){return `<div class="demo-bar">Independent design concept <span>·</span> Sample products <span>·</span> No live orders</div><header class="site-header"><nav class="desktop-nav" aria-label="Main navigation"><a href="#/shop">Shop the edit</a><a href="#/categories">Collections</a><a href="#/about">Our story</a></nav><button class="icon-button menu-toggle" data-action="menu" aria-label="Open menu">${icon('menu')}</button><a href="#/" class="wordmark" aria-label="Luxvibe home">LUXVIBE<small>THE EVERYDAY EDIT</small></a><div class="header-actions"><button class="icon-button" data-action="search" aria-label="Search products">${icon('search')}</button><a class="icon-button header-wishlist" href="#/wishlist" aria-label="Wishlist">${icon('heart')}<span class="badge wish-count" ${!wishlist.length?'hidden':''}>${wishlist.length}</span></a><button class="icon-button" data-action="cart" aria-label="Open shopping bag">${icon('shopping-bag')}<span class="badge cart-count" ${!count()?'hidden':''}>${count()}</span></button></div></header>`;}
function bottomNav(){return `<nav class="bottom-nav" aria-label="Mobile navigation"><a href="#/" class="${route==='/'?'active':''}" ${route==='/'?'aria-current="page"':''}>${icon('house')}Home</a><a href="#/categories" class="${route.startsWith('/categories')||route.startsWith('/collection')?'active':''}">${icon('layout-grid')}Categories</a><button data-action="search" class="${route==='/search'?'active':''}">${icon('search')}Search</button><a href="#/wishlist" class="${route==='/wishlist'?'active':''}">${icon('heart')}Wishlist<span class="badge wish-count" ${!wishlist.length?'hidden':''}>${wishlist.length}</span></a><a href="#/cart" class="${route==='/cart'?'active':''}">${icon('shopping-bag')}Cart<span class="badge cart-count" ${!count()?'hidden':''}>${count()}</span></a></nav>`;}
function footer(){return `<footer class="footer"><div class="footer-grid"><div class="footer-brand"><a href="#/" class="wordmark">LUXVIBE</a><p>A thoughtful edit for the everyday.<br>Discover the boutique shopping concept.</p><p>Independent proposal by <a href="https://fazhere.com" target="_blank" rel="noopener noreferrer">Fazhere ${icon('arrow-up-right')}</a>.</p></div><div><h3>Explore</h3><div class="footer-links"><a href="#/shop">Shop all</a><a href="#/categories">Collections</a><a href="#/wishlist">Your wishlist</a><a href="#/about">Our story</a></div></div><div><h3>Here to help</h3><div class="footer-links"><a href="#/contact">Contact</a><a href="#/shipping">Shipping information</a><a href="#/returns">Returns & replacement</a><a href="#/privacy">Privacy</a><a href="#/terms">Terms</a></div></div><div><h3>Stay in the loop</h3><div class="footer-links"><a href="${esc(instagram())}" target="_blank" rel="noopener noreferrer">Instagram ${icon('arrow-up-right')}</a><button class="text-link" data-action="contact-preview">WhatsApp enquiry ${icon('message-circle')}</button><a href="#/admin/login">Owner demo ${icon('arrow-up-right')}</a></div></div></div><div class="footer-bottom"><span>Luxvibe boutique concept · All products, prices & imagery are illustrative.</span><span>Created for review. No payments, live orders or customer accounts.</span></div></footer>`;}
function categoryTiles(){const cats=[['Bags','bag','For everything you carry'],['Wallets','wallet','The little essentials'],['Watches','watch','Time for the details']];return `<div class="categories-grid">${cats.map(([cat,img,caption])=>`<a class="category-card" href="#/collection/${cat.toLowerCase()}"><img src="${ASSETS}${img}-800.webp" alt="Sample ${cat.toLowerCase()} collection" width="800" height="800" loading="lazy"><div class="category-label"><div><span>${caption}</span><h3>${cat}</h3></div>${icon('arrow-up-right')}</div></a>`).join('')}</div>`;}
function home(){return `<section class="hero"><div class="hero-copy"><span class="eyebrow">${esc(settings.banner)}</span><h1 aria-label="${esc(settings.headline)}">${settings.headline===DEFAULT_SETTINGS.headline?'Discover your<br><em>everyday</em><br class="desktop-break"><span class="mobile-space"> </span>luxury.':esc(settings.headline)}</h1><p>A considered edit of bags and finishing touches.<br>Find a little something that feels like you.</p><div class="hero-actions"><a href="#/shop" class="btn">Shop the collection ${icon('arrow-right')}</a><a href="#/shop?sort=featured" class="text-link">Explore the edit ${icon('arrow-up-right')}</a></div><div class="hero-note">${icon('sparkles')}A sample collection, thoughtfully presented.</div></div><div class="hero-image"><img src="${ASSETS}hero-1440.webp" srcset="${ASSETS}hero-640.webp 640w, ${ASSETS}hero-960.webp 960w, ${ASSETS}hero-1440.webp 1440w" sizes="(max-width:760px) 100vw, 60vw" alt="Burgundy concept handbag in warm sunlight on a travertine plinth" width="1672" height="941" fetchpriority="high"><a href="#/product/muse-top-handle" class="hero-caption"><div><span class="eyebrow">IN THE SPOTLIGHT · SAMPLE</span><strong>The Muse Top Handle</strong></div>${icon('arrow-up-right')}</a></div></section><div class="benefits"><div class="benefit">${icon('layout-grid')}<div><strong>A considered collection</strong><small>Discover your everyday favourites</small></div></div><div class="benefit">${icon('heart')}<div><strong>Keep what you love</strong><small>A wishlist, ready when you are</small></div></div><div class="benefit">${icon('message-circle')}<div><strong>A personal conversation</strong><small>Explore the WhatsApp enquiry flow</small></div></div></div><section class="section" id="the-edit"><div class="section-head"><div><span class="eyebrow">A LITTLE SOMETHING FOR YOU</span><h2>The everyday favourites</h2><p>Small details. A lasting impression.</p></div><a href="#/shop" class="text-link">View all pieces ${icon('arrow-up-right')}</a></div><div class="product-grid">${products.filter(p=>p.featured&&!p.archived).slice(0,4).map(card).join('')}</div><p class="sample-caption">A sample edit · Illustrative products, pricing and AI-generated imagery. The official Luxvibe collection will be added with the owner’s approval.</p></section><section class="section category-section"><div class="section-head"><div><span class="eyebrow">FIND YOUR NEXT FAVOURITE</span><h2>A world of little luxuries</h2></div><a href="#/categories" class="text-link">All collections ${icon('arrow-up-right')}</a></div>${categoryTiles()}</section><section class="story-section"><div class="story-photo"><img src="${ASSETS}hero-960.webp" alt="Detail of an illustrative burgundy handbag in natural light" width="960" height="540" loading="lazy"><span class="photo-note">A study in everyday details · Concept imagery</span></div><div class="story-copy"><span class="eyebrow">BROWSE. CHOOSE. SAY HELLO.</span><h2>Good finds.<br>Simple beginnings.</h2><p>All the ease of browsing a boutique, with the comfort of a personal conversation.</p><div class="how-step"><span>01</span><div><strong>Discover your piece</strong><p>Explore the collection and find your favourite.</p></div></div><div class="how-step"><span>02</span><div><strong>Make it your edit</strong><p>Choose an option. Save it or add it to your bag.</p></div></div><div class="how-step"><span>03</span><div><strong>Start a conversation</strong><p>Preview a WhatsApp enquiry with everything in one place.</p></div></div><a href="#/about" class="text-link">Meet the concept ${icon('arrow-up-right')}</a></div></section><section class="reviews-placeholder"><span class="eyebrow">THE STORIES BEHIND THE PIECES</span><h2>Real moments, shared with love.</h2><p>${esc(settings.reviewNote)}</p><a href="${esc(instagram())}" target="_blank" rel="noopener noreferrer" class="text-link">Explore Luxvibe on Instagram ${icon('arrow-up-right')}</a></section><section class="social-banner"><div><span class="eyebrow">THE EDIT CONTINUES</span><h2>A little inspiration,<br><em>every day.</em></h2><p>Visit Luxvibe’s Instagram for the business’s own posts and updates.</p></div><a class="btn" href="${esc(instagram())}" target="_blank" rel="noopener noreferrer">${icon('instagram')} @l_ux_vibe ${icon('arrow-up-right')}</a></section>`;}
function categories(){return `<div class="page-heading"><span class="eyebrow">FIND YOUR EVERYDAY</span><h1>The collections</h1><p>Explore the sample edit, one little luxury at a time.</p></div><section class="section" style="padding-top:10px">${categoryTiles()}<a href="#/collection/eyewear" class="text-link" style="margin-top:25px">Explore eyewear ${icon('arrow-up-right')}</a><p class="sample-caption">These are demonstration categories, awaiting the owner’s actual catalog.</p></section>`;}
function collectionPage(isSearch=false){const category=route.startsWith('/collection/')?CATEGORIES.find(c=>c.toLowerCase()===route.split('/')[2]):'All';if(!category)return notFound();filters={query:params().get('q')||'',category,max:10000,available:false,colour:'All',sort:params().get('sort')||'featured'};return `<div class="page-heading"><span class="eyebrow">THE SAMPLE COLLECTION</span><h1>${isSearch?'Find your favourite':category==='All'?'The everyday edit':esc(category)}</h1><p>${isSearch?'Search the sample boutique by product, category or colour.':'Thoughtfully chosen details, waiting to become your favourites.'}</p></div><section class="collection"><div class="collection-tabs"><a class="pill ${category==='All'?'active':''}" href="#/shop">All pieces</a>${CATEGORIES.map(c=>`<a href="#/collection/${c.toLowerCase()}" class="pill ${category===c?'active':''}">${c}</a>`).join('')}</div><div class="filters"><input type="search" data-filter="query" value="${esc(filters.query)}" aria-label="Search this collection" placeholder="Search the edit…"><label>Price <select data-filter="max" aria-label="Maximum price"><option value="10000">All prices</option><option value="1000">Under ₹1,000</option><option value="2000">Under ₹2,000</option></select></label><label>Colour <select data-filter="colour" aria-label="Filter by colour"><option>All</option>${[...new Set(products.filter(p=>!p.archived).map(p=>p.colour))].map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><label><input type="checkbox" data-filter="available"> Available</label><span class="filter-count" id="filter-count"></span><label>Sort <select data-filter="sort" aria-label="Sort products"><option value="featured">Featured</option><option value="newest">Newest</option><option value="price-asc">Price: low to high</option><option value="price-desc">Price: high to low</option></select></label></div><div class="product-grid" id="collection-results"></div><p class="sample-caption">All prices and stock are for demonstration. No real purchases can be made.</p></section>`;}
function updateCollection(){const items=filterProducts(products,filters);$('#collection-results').innerHTML=items.length?items.map(card).join(''):`<div class="empty">${icon('search')}<h2>No pieces found.</h2><p>Try another search or clear your filters.</p><button class="btn outline" data-action="clear-filters">Clear filters</button></div>`;$('#filter-count').textContent=`${items.length} ${items.length===1?'piece':'pieces'}`;icons();}
function pdp(){const p=products.find(p=>p.id===safeDecode(route.split('/')[2]||'')&&!p.archived);if(!p)return notFound();selectedVariant=p.variants.find(v=>v.stock>0)?.name||p.variants[0].name;selectedQuantity=1;galleryDetail=false;return `<div class="breadcrumbs"><a href="#/">Home</a><span>/</span><a href="#/collection/${p.category.toLowerCase()}">${esc(p.category)}</a><span>/</span><span>${esc(p.name)}</span></div><section class="pdp"><div class="pdp-media"><button class="pdp-main-image" data-action="zoom" data-id="${esc(p.id)}" aria-label="Enlarge ${esc(p.name)} image">${image(p,'',true)}<span class="zoom-icon">${icon('expand')}</span></button><div class="gallery-thumbs"><button class="gallery-thumb active" data-action="gallery" data-view="product" aria-label="Show full product image" aria-pressed="true">${image(p)}</button><button class="gallery-thumb detail" data-action="gallery" data-view="detail" aria-label="Show cropped detail of the same concept image" aria-pressed="false">${image(p)}</button><span>Concept image<br>Product & detail crop</span></div></div><div class="pdp-info"><span class="eyebrow">${esc(p.category)} · THE SAMPLE EDIT</span><h1>${esc(p.name)}</h1><div class="pdp-price">${money(p.price)}</div><p class="tiny">Illustrative price. Final product details await approval.</p><p class="pdp-description">${esc(p.description)}</p><div class="option-group"><span class="option-label">Colour — ${esc(p.colour)}</span><span class="swatch-label"><span class="swatch-dot" style="--colour:${/^#[a-f\d]{6}$/i.test(p.hex)?p.hex:'#591f2b'}"></span>${esc(p.colour)}</span></div><div class="option-group"><span class="option-label">${p.category==='Watches'?'Strap size':'Option'} — <span id="selected-option">${esc(selectedVariant)}</span></span><div class="variant-options">${p.variants.map(v=>`<button class="variant ${selectedVariant===v.name?'active':''}" data-action="variant" data-id="${esc(p.id)}" data-variant="${esc(v.name)}" aria-pressed="${selectedVariant===v.name}" aria-disabled="${v.stock<1}">${esc(v.name)}${v.stock<1?' · unavailable':''}</button>`).join('')}</div></div><p class="tiny" id="stock-note">${p.variants.some(v=>v.stock>0)?'Available in the demo · Actual stock unverified':'Unavailable in this demo'}</p><div class="buy-row"><div class="qty"><button data-action="pdp-qty" data-delta="-1" data-id="${esc(p.id)}" aria-label="Decrease quantity">−</button><span id="pdp-qty" aria-live="polite">1</span><button data-action="pdp-qty" data-delta="1" data-id="${esc(p.id)}" aria-label="Increase quantity">+</button></div><button class="btn neutral" data-action="add" data-id="${esc(p.id)}" ${!p.variants.some(v=>v.stock>0)?'disabled':''}>Add to bag ${icon('plus')}</button></div><button class="btn full outline" data-action="product-enquiry" data-id="${esc(p.id)}" ${!p.variants.some(v=>v.stock>0)?'disabled':''}>${icon('message-circle')} Preview WhatsApp enquiry ${icon('arrow-up-right')}</button><div class="pdp-note">${icon('info')}<span>This is a design demonstration. No order is placed and no message is sent. Images are AI-generated sample visuals.</span></div><details open><summary>Details & materials</summary><p>${esc(p.spec)}</p></details><details><summary>Delivery & payment</summary><p>${esc(settings.shipping)} Delivery charges, payment options and COD eligibility must be confirmed separately.</p></details><details><summary>Returns & replacement</summary><p>${esc(settings.returns)}</p></details><button class="text-link" data-action="wish" data-id="${esc(p.id)}">${icon('heart')} ${wishlist.includes(p.id)?'Remove from wishlist':'Save to your wishlist'}</button></div></section><section class="section related"><div class="section-head"><div><span class="eyebrow">COMPLETE YOUR EDIT</span><h2>A few more favourites</h2></div><a class="text-link" href="#/shop">Shop all ${icon('arrow-up-right')}</a></div><div class="product-grid">${products.filter(x=>x.id!==p.id&&!x.archived).slice(0,4).map(card).join('')}</div></section><div class="pdp-sticky"><div><strong>${money(p.price)}</strong><small>Sample price</small></div><button class="btn" data-action="add" data-id="${esc(p.id)}" ${!p.variants.some(v=>v.stock>0)?'disabled':''}>Add to bag ${icon('shopping-bag')}</button></div>`;}
function cartItem(row){const p=row.product;return `<article class="cart-item"><a href="${productLink(p)}">${image(p)}</a><div><h3><a href="${productLink(p)}">${esc(p.name)}</a></h3><p>${esc(p.colour)} · ${esc(row.variant)}</p><p>${money(p.price)} each · Sample</p><div class="qty"><button data-action="cart-qty" data-id="${esc(p.id)}" data-variant="${esc(row.variant)}" data-delta="-1" aria-label="Decrease ${esc(p.name)} quantity">−</button><span>${row.quantity}</span><button data-action="cart-qty" data-id="${esc(p.id)}" data-variant="${esc(row.variant)}" data-delta="1" aria-label="Increase ${esc(p.name)} quantity">+</button></div></div><div class="cart-item-right">${money(p.price*row.quantity)}<br><button class="remove" data-action="remove" data-id="${esc(p.id)}" data-variant="${esc(row.variant)}">Remove</button></div></article>`;}
function emptyBag(){return `<div class="empty">${icon('shopping-bag')}<h2>Your next favourite<br>is waiting.</h2><p>Your shopping bag is empty.</p><a href="#/shop" class="btn">Explore the edit ${icon('arrow-right')}</a></div>`;}
function cartSummary(){return `<aside class="cart-summary"><h2>Your edit, together.</h2><div class="summary-line"><span>Subtotal · ${count()} ${count()===1?'piece':'pieces'}</span><span>${money(subtotal(cart,products))}</span></div><div class="summary-line"><span>Delivery</span><span>To be confirmed</span></div><div class="summary-line total"><span>Displayed subtotal</span><span>${money(subtotal(cart,products))}</span></div><p class="tiny">Sample pricing. Final prices, availability, shipping and COD eligibility need confirmation.</p><button class="btn full" data-action="checkout">${icon('message-circle')} Preview WhatsApp enquiry ${icon('arrow-up-right')}</button><p class="tiny">No payment is collected. Previewing an enquiry does not place or confirm an order.</p><a class="text-link" href="#/shop">Continue exploring ${icon('arrow-right')}</a></aside>`;}
function cartPage(){return `<div class="page-heading cart-heading"><span class="eyebrow">A LITTLE COLLECTION OF YOU</span><h1>Your shopping bag</h1><p>Everything you’ve had your eye on, in one place.</p></div>${cart.length?`<div class="cart-layout"><div>${cartLines(cart,products).map(cartItem).join('')}</div>${cartSummary()}</div>`:emptyBag()}`;}
function wishPage(){const items=products.filter(p=>wishlist.includes(p.id)&&!p.archived);return `<div class="page-heading"><span class="eyebrow">KEPT CLOSE</span><h1>Your wishlist</h1><p>For the pieces you keep coming back to.</p></div><section class="section" style="padding-top:10px"><div class="product-grid">${items.length?items.map(card).join(''):`<div class="empty">${icon('heart')}<h2>Love it? Save it.</h2><p>Tap the heart on any piece to keep it here.</p><a href="#/shop" class="btn">Find your favourites ${icon('arrow-right')}</a></div>`}</div></section>`;}
function editorialPage(type){const pages={about:['THE IDEA BEHIND THE EDIT','A little more Luxvibe.',settings.story,`<h2>A more personal way to browse.</h2><p>The concept brings product discovery, saved favourites and a shopping bag into one place. An enquiry preview keeps the selected products and options together for a WhatsApp conversation.</p>`],shipping:['HERE TO HELP','Shipping information',settings.shipping,'<h2>Before a real purchase</h2><p>Ask the business to confirm delivery coverage, fees, dispatch timing, tracking, COD availability and any advance-payment requirements. No delivery dates are promised by this demo.</p>'],returns:['HERE TO HELP','Returns & replacement',settings.returns,'<h2>Details to confirm</h2><p>The owner needs to approve eligible products, the guarantee period, exclusions, condition requirements, proof of purchase, return shipping costs and the claim process.</p>'],privacy:['PROTOTYPE INFORMATION','Your privacy.', 'This demonstration stores your bag, wishlist, owner-demo settings and any manually recorded sample enquiries in this browser’s local storage. It uses no analytics, customer accounts or payment collection. This is a public design concept. No customer account is required.', '<h2>Your choices</h2><p>Clear the demo data below to remove this prototype’s stored information. Uploaded owner-demo images stay in this browser. Instagram links take you to Instagram, which has its own privacy terms.</p><p>The enquiry preview does not send anything. The owner settings can generate a click-to-chat URL, but outbound ordering is disabled in this concept.</p><button class="btn outline" data-action="clear-data">Clear this browser’s demo data</button>'],terms:['PROTOTYPE INFORMATION','Terms of this concept.', 'This is an independent, unapproved design proposal prepared by Fazhere for review. It is not an official Luxvibe store. Products, prices, availability, categories and AI-generated images are illustrative. Nothing shown is an offer for sale.', '<h2>Using the demonstration</h2><p>Cart actions and enquiries do not create orders, contracts, reservations, payments or customer-service requests. Owner controls are a browser-local simulation and are not secure production administration.</p><p>The business must approve its identity, inventory, content, contact details and legal policies before an authorized launch.</p>'],contact:['A CONVERSATION STARTS HERE','Say hello.', 'Explore the business’s Instagram account, or try the enquiry preview to see how a shopper could ask about a piece. The receiving WhatsApp number has not been verified.', '<div class="contact-options"><a href="'+esc(instagram())+'" class="btn" target="_blank" rel="noopener noreferrer">'+icon('instagram')+' Visit Instagram '+icon('arrow-up-right')+'</a><button class="btn outline" data-action="contact-preview">'+icon('message-circle')+' Try enquiry preview</button></div>']};const [eyebrow,title,body,more]=pages[type];return `<article class="editorial-page"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${esc(body)}</p>${more}<div class="notice">Independent concept for review. Business details and policies require the owner’s approval before launch.</div></article>`;}
function notFound(){return `<section class="error-page"><span class="eyebrow">A LITTLE DETOUR</span><h1>404</h1><h2>This piece of the story is missing.</h2><p>The page may have moved, or the product may be archived.</p><a href="#/shop" class="btn">Back to the edit ${icon('arrow-right')}</a></section>`;}
function params(){return new URLSearchParams(location.hash.split('?')[1]||'');}
function render(){closeModal();try{route=decodeURI((location.hash.slice(1)||'/').split('?')[0]);}catch{route='/404';}document.body.classList.toggle('pdp-route',route.startsWith('/product/'));cart=normaliseCart(cart,products);wishlist=wishlist.filter(id=>products.some(p=>p.id===id&&!p.archived));let content;if(route==='/')content=home();else if(route==='/shop'||route==='/search'||route.startsWith('/collection/'))content=collectionPage(route==='/search');else if(route==='/categories')content=categories();else if(route.startsWith('/product/'))content=pdp();else if(route==='/cart')content=cartPage();else if(route==='/wishlist')content=wishPage();else if(['/about','/shipping','/returns','/privacy','/terms','/contact'].includes(route))content=editorialPage(route.slice(1));else if(route.startsWith('/admin'))content=adminPage();else content=notFound();$('#app').innerHTML=header()+`<main id="main" class="page-wrap" tabindex="-1">${content}</main>`+footer()+bottomNav();document.title=(route.startsWith('/product/')?products.find(p=>p.id===safeDecode(route.split('/')[2]||''))?.name+' — ':route.startsWith('/admin')?'Owner Demo — ':'')+settings.title;document.querySelector('meta[name=description]').content=settings.description;icons();if($('#collection-results')){$('[data-filter=sort]').value=filters.sort;updateCollection();}updateCounts();}
function showModal(title,body,kind=''){modal.className=kind;modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('x')}</button></div><div class="modal-body">${body}</div>`;icons();if(!modal.open)modal.showModal();else $('[data-action="close"]',modal).focus();}
function closeModal(){if(modal.open)modal.close();}
function showCart(){showModal('Your shopping bag',cart.length?cartLines(cart,products).map(cartItem).join('')+`<div style="margin-top:28px">${cartSummary()}<a href="#/cart" class="text-link">View full shopping bag ${icon('arrow-right')}</a></div>`:emptyBag(),'drawer');}
function showSearch(){showModal('Find your favourite',`<div class="search-input-wrap">${icon('search')}<input type="search" id="live-search" aria-label="Search products" placeholder="A bag, a colour, a little luxury…" autocomplete="off"></div><div class="search-categories">${CATEGORIES.map(c=>`<a class="pill" href="#/collection/${c.toLowerCase()}">${c}</a>`).join('')}</div><div id="search-results"></div><a id="search-all" href="#/search" class="text-link">See all search results ${icon('arrow-right')}</a>`);updateSearch('');$('#live-search').focus();}
function updateSearch(query){const items=filterProducts(products,{query}).slice(0,5);$('#search-results').innerHTML=items.length?items.map(p=>`<a href="${productLink(p)}" class="search-result">${image(p)}<div><h3>${esc(p.name)}</h3><p>${money(p.price)} · Sample</p></div>${icon('arrow-up-right')}</a>`).join(''):'<p class="search-empty">No pieces found. Try a product, colour or category.</p>';$('#search-all').href='#/search?q='+encodeURIComponent(query);icons();}
function showEnquiry(rows){enquiryCart=normaliseCart(rows,products);if(!enquiryCart.length)return toast('Add a piece to your bag first.');const message=enquiryMessage(enquiryCart,products,DEMO_URL,'LV-DEMO-'+new Date().toISOString().slice(0,10).replaceAll('-',''));showModal('A conversation, prepared.',`<p class="tiny">Review how the selected pieces would appear in an enquiry.</p><div class="notice">Demo only. The business’s receiving number is unverified. Live WhatsApp ordering is disabled; nothing is sent or recorded as an order.</div><label class="option-label" for="enquiry-message">Sample WhatsApp message</label><textarea id="enquiry-message" class="checkout-text" readonly>${esc(message)}</textarea><div class="dialog-actions"><button class="btn" data-action="copy-enquiry">${icon('copy')} Copy sample message</button><button class="btn outline" data-action="close">Continue browsing</button></div><p class="tiny" style="margin-top:16px">Shipping and COD remain subject to confirmation. Opening a chat would not confirm an order.</p>`);}
function instagram(){try{const u=new URL(settings.instagram);return u.protocol==='https:'&&['instagram.com','www.instagram.com'].includes(u.hostname)?u.href:DEFAULT_SETTINGS.instagram;}catch{return DEFAULT_SETTINGS.instagram;}}
function adminPage(){if(route==='/admin/login'||!ownerDemo)return `<section class="owner-entry"><span class="eyebrow">FOR THE BUSINESS OWNER</span><h1>Your boutique,<br>behind the scenes.</h1><p>Try a simplified product and content dashboard. This is an open demonstration, with changes saved only in your current browser.</p><div class="notice">This is not a secure admin login. No server, authentication, real orders or shared database is connected. Use sample information only.</div><label class="form-check"><input type="checkbox" id="owner-ack"><span>I understand this is a browser-local demonstration.</span></label><button class="btn full" data-action="enter-owner">Enter the owner demo ${icon('arrow-right')}</button></section>`;
const tab=route.split('/')[2]||'overview';const tabs=[['overview','Overview'],['products','Products'],['settings','Store settings'],['content','Content'],['enquiries','Enquiries']];let inner='';
if(tab==='overview')inner=`<div class="stat-grid"><div class="stat"><span>Visible sample products</span><strong>${products.filter(p=>!p.archived).length}</strong></div><div class="stat"><span>Featured pieces</span><strong>${products.filter(p=>p.featured&&!p.archived).length}</strong></div><div class="stat"><span>Manually recorded demo enquiries</span><strong>${enquiries.length}</strong></div></div><div class="content-preview"><span class="eyebrow">READY TO EXPLORE</span><h2 style="font-size:34px;margin:16px 0">A simpler way to run the edit.</h2><p style="font-size:12px">Edit sample products, change homepage copy, try inventory updates and configure a receiving number. Your changes affect this browser only.</p><div class="dialog-actions"><a class="btn" href="#/admin/products">Manage products ${icon('arrow-right')}</a><a class="btn outline" href="#/">View the boutique ${icon('arrow-up-right')}</a><button class="text-link" data-action="export">Export demo data ${icon('download')}</button></div></div><div class="notice admin-note">No revenue or order metrics are fabricated. Previewing or copying a WhatsApp message creates no order and is not counted as a customer enquiry.</div>`;
else if(tab==='products')inner=`<div class="section-head"><p>${products.length} sample products · Stock is simulated</p><button class="btn" data-action="edit-product" data-id="new">${icon('plus')} Add a product</button></div><div class="admin-list">${products.map(p=>`<div class="admin-row">${image(p)}<div>${esc(p.name)}<br><small class="tiny">${esc(p.category)}</small></div><span class="admin-extra">${money(p.price)}</span><span class="admin-extra status-pill ${p.archived?'archived':''}">${p.archived?'Archived':'Visible'}</span><button class="btn outline" data-action="edit-product" data-id="${esc(p.id)}">Edit</button></div>`).join('')}</div>`;
else if(tab==='settings')inner=`<form id="settings-form" class="admin-form"><div class="field"><label for="setting-whatsapp">Receiving WhatsApp number, with country code</label><input id="setting-whatsapp" name="whatsapp" value="${esc(settings.whatsapp)}" placeholder="e.g. 91XXXXXXXXXX" inputmode="tel" maxlength="22"><small>Blank by default. The owner must verify the number. Saving never enables live ordering in this prototype.</small></div><div class="field"><label for="setting-instagram">Instagram profile URL</label><input id="setting-instagram" name="instagram" type="url" required value="${esc(instagram())}"><small>Only HTTPS Instagram profile URLs are accepted.</small></div><div class="form-error" role="alert"></div><div><button type="submit" class="btn">Save local settings ${icon('check')}</button></div></form><div class="content-preview"><h2 style="font-size:30px">Click-to-chat link builder</h2><p style="font-size:11px;margin:14px 0">Generate and inspect an official wa.me URL with sample text. It does not open WhatsApp or send a message.</p><button class="btn outline" data-action="test-link">Generate sample link</button><div id="test-link-result"></div></div>`;
else if(tab==='content')inner=`<form id="content-form" class="admin-form">${[['banner','Hero eyebrow','text'],['headline','Hero headline','text'],['story','About Luxvibe','textarea'],['shipping','Shipping information — unverified until approved','textarea'],['returns','Replacement information — unverified until approved','textarea'],['reviewNote','Customer experiences placeholder','textarea'],['title','SEO title','text'],['description','SEO description','textarea']].map(([key,label,type])=>`<div class="field"><label for="content-${key}">${label}</label>${type==='textarea'?`<textarea id="content-${key}" name="${key}" maxlength="1800" required>${esc(settings[key])}</textarea>`:`<input id="content-${key}" name="${key}" value="${esc(settings[key])}" maxlength="150" required>`}</div>`).join('')}<div class="form-error" role="alert"></div><div><button type="submit" class="btn">Save local content ${icon('check')}</button></div></form><div class="notice">No testimonials have been invented. Publish customer reviews only after receiving authentic content and permission. This demo remains noindex.</div>`;
else if(tab==='enquiries')inner=`<div class="notice">These are manually recorded sample enquiries. WhatsApp previews, clicks and copied messages are not customer conversations or confirmed orders. Nothing is synced with WhatsApp.</div><form id="enquiry-form" class="admin-form"><div class="two-fields"><div class="field"><label for="enquiry-label">Sample enquiry label</label><input id="enquiry-label" name="label" placeholder="e.g. Sample bag enquiry" maxlength="100" required></div><div class="field"><label for="enquiry-product">Sample product</label><select id="enquiry-product" name="product">${products.map(p=>`<option value="${esc(p.name)}">${esc(p.name)}</option>`).join('')}</select></div></div><div><button class="btn" type="submit">Add a sample enquiry ${icon('plus')}</button></div><p class="tiny">Use sample labels only. Do not enter real customer information.</p></form><div style="margin-top:30px">${enquiries.length?enquiries.map(e=>`<div class="enquiry-row"><div>${esc(e.label)}<small>${esc(e.product)} · Manually entered sample</small></div><select data-enquiry="${esc(e.id)}" aria-label="Sample status for ${esc(e.label)}">${['New','Discussing','Closed'].map(s=>`<option ${s===e.status?'selected':''}>${s}</option>`).join('')}</select></div>`).join(''):'<p class="tiny">No manually recorded sample enquiries yet.</p>'}</div>`;
else return notFound();return `<section class="admin"><div class="admin-heading"><div><span class="eyebrow">BROWSER-LOCAL OWNER DEMO</span><h1 style="margin-top:12px">The boutique studio</h1></div><button class="btn outline" data-action="leave-owner">Leave demo ${icon('log-out')}</button></div><nav class="admin-tabs" aria-label="Owner demo">${tabs.map(([id,name])=>`<a class="${tab===id?'active':''}" href="#/admin/${id}">${name}</a>`).join('')}</nav>${inner}</section>`;}
function editProduct(id){editingProduct=id==='new'?null:products.find(p=>p.id===id);const p=editingProduct||{name:'',category:'Bags',price:1000,colour:'',hex:'#591f2b',image:'bag',featured:false,archived:false,variants:[{name:'One size',stock:5}],description:'',spec:''};uploadedImage=p.image;showModal(editingProduct?'Edit sample product':'Add a sample product',`<form id="product-form" class="admin-form"><p class="tiny">Edits and uploads stay in this browser. No server or inventory feed is connected.</p><div class="field"><label for="product-name">Product name</label><input id="product-name" name="name" maxlength="100" value="${esc(p.name)}" required></div><div class="two-fields"><div class="field"><label for="product-category">Category</label><select id="product-category" name="category">${CATEGORIES.map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label for="product-price">Sample price (₹)</label><input id="product-price" name="price" type="number" min="1" max="1000000" step="1" value="${p.price}" required></div></div><div class="two-fields"><div class="field"><label for="product-colour">Colour name</label><input id="product-colour" name="colour" maxlength="50" value="${esc(p.colour)}" required></div><div class="field"><label for="product-hex">Colour swatch</label><input id="product-hex" name="hex" type="color" value="${/^#[a-f\d]{6}$/i.test(p.hex)?p.hex:'#591f2b'}"></div></div><div class="field"><label for="product-variants">Options and simulated stock</label><textarea id="product-variants" name="variants" required>${esc(p.variants.map(v=>v.name+':'+v.stock).join('\n'))}</textarea><small>One per line: option name:quantity. Example: S/M:5. Use 0 to mark an option unavailable.</small></div><div class="field"><label for="product-image">Concept image</label><select id="product-image" name="image"><option value="current">Keep current image</option>${['hero','bag','wallet','watch','sunglasses'].map(v=>`<option value="${v}">${v==='hero'?'Burgundy bag':v}</option>`).join('')}</select><small>Built-in images are AI-generated. Match the colour and specifications to your chosen photo.</small></div><div class="field"><label for="product-upload">Or upload a sample photo</label><input id="product-upload" type="file" accept="image/jpeg,image/png,image/webp"><small>JPEG, PNG or WebP, at most 600 KB; stored locally. SVG and other files are rejected.</small></div><div class="field"><label for="product-description">Description</label><textarea id="product-description" name="description" maxlength="1500" required>${esc(p.description)}</textarea></div><div class="field"><label for="product-spec">Details & material note</label><textarea id="product-spec" name="spec" maxlength="1500" required>${esc(p.spec)}</textarea></div><div class="two-fields"><label class="form-check"><input name="featured" type="checkbox" ${p.featured?'checked':''}>Featured on homepage</label><label class="form-check"><input name="archived" type="checkbox" ${p.archived?'checked':''}>Archive this sample</label></div><div class="form-error" role="alert"></div><button type="submit" class="btn">Save local product ${icon('check')}</button></form>`);}
async function onAction(e){const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;const p=products.find(p=>p.id===id);try{
if(action==='skip'){e.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'});}
else if(action==='close')closeModal();
else if(action==='menu')showModal('Explore the edit',`<nav class="mobile-nav-panel"><a href="#/shop">Shop the edit</a><a href="#/categories">Collections</a><a href="#/about">Our story</a><a href="#/contact">Say hello</a><a href="#/admin/login">Owner demo</a></nav>`,'drawer');
else if(action==='search')showSearch();else if(action==='cart')showCart();
else if(action==='wish'){if(!p)return;const saved=wishlist.includes(id);wishlist=saved?wishlist.filter(x=>x!==id):[...wishlist,id];persist('wishlist',wishlist);if(route==='/wishlist'){render();}else{$$('[data-action=wish]').filter(btn=>btn.dataset.id===id).forEach(btn=>{if(btn.classList.contains('heart')){btn.classList.toggle('saved',!saved);btn.setAttribute('aria-pressed',String(!saved));btn.setAttribute('aria-label',`${saved?'Save':'Remove'} ${p.name} ${saved?'to':'from'} wishlist`);}else btn.innerHTML=icon('heart')+(saved?' Save to your wishlist':' Remove from wishlist');});icons();}updateCounts();toast(saved?'Removed from your wishlist.':'Kept close. Added to your wishlist.');}
else if(action==='variant'){const v=p.variants.find(v=>v.name===el.dataset.variant);if(v.stock<1)return toast('This sample option is unavailable. Choose another option.');selectedVariant=v.name;selectedQuantity=1;$('#selected-option').textContent=v.name;$('#pdp-qty').textContent=1;$$('.variant').forEach(b=>{b.classList.toggle('active',b.dataset.variant===v.name);b.setAttribute('aria-pressed',String(b.dataset.variant===v.name));});}
else if(action==='pdp-qty'){const stock=p.variants.find(v=>v.name===selectedVariant)?.stock||0;const n=selectedQuantity+Number(el.dataset.delta);if(n>stock)return toast('That exceeds the sample availability.');selectedQuantity=Math.max(1,n);$('#pdp-qty').textContent=selectedQuantity;}
else if(action==='add'){cart=addToCart(cart,products,id,selectedVariant,selectedQuantity);saveCart();showCart();toast('Added to your shopping bag.');}
else if(action==='product-enquiry'){showEnquiry([{id,variant:selectedVariant,quantity:selectedQuantity}]);}
else if(action==='checkout')showEnquiry(cart);
else if(action==='copy-enquiry'){const text=$('#enquiry-message').value;try{await navigator.clipboard.writeText(text);toast('Sample message copied. Nothing was sent.');}catch{$('#enquiry-message').select();toast('Select and copy the sample message. Nothing was sent.');}}
else if(action==='contact-preview'){const sample=products.find(p=>!p.archived&&p.variants.some(v=>v.stock>0));if(sample)showEnquiry([{id:sample.id,variant:sample.variants.find(v=>v.stock>0).name,quantity:1}]);else toast('No available sample products to preview.');}
else if(action==='cart-qty'||action==='remove'){const row=cart.find(r=>r.id===id&&r.variant===el.dataset.variant);if(!row)return;const wasModal=modal.open;if(action==='remove')cart=cart.filter(r=>r!==row);else{const n=row.quantity+Number(el.dataset.delta);const max=p.variants.find(v=>v.name===row.variant)?.stock||0;if(n>max)return toast('That exceeds the sample availability.');if(n<=0)cart=cart.filter(r=>r!==row);else row.quantity=n;}saveCart();if(wasModal){if(route==='/cart')render();showCart();}else render();}
else if(action==='gallery'){galleryDetail=el.dataset.view==='detail';$('.pdp-main-image').classList.toggle('detail',galleryDetail);$$('.gallery-thumb').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',String(b===el));});}
else if(action==='zoom')showModal('A closer look',image(p,'',true),'zoom-dialog');
else if(action==='clear-filters'){filters={query:'',category:filters.category,max:10000,available:false,colour:'All',sort:'featured'};$$('[data-filter]').forEach(f=>{if(f.type==='checkbox')f.checked=false;else f.value=filters[f.dataset.filter];});updateCollection();}
else if(action==='enter-owner'){if(!$('#owner-ack').checked)return toast('Please acknowledge that this is a local demo.');ownerDemo=true;try{sessionStorage.setItem('luxvibe.owner','yes');}catch{}location.hash='/admin/overview';}
else if(action==='leave-owner'){ownerDemo=false;try{sessionStorage.removeItem('luxvibe.owner');}catch{}location.hash='/admin/login';}
else if(action==='edit-product'){if(!ownerDemo)return;editProduct(id);}
else if(action==='test-link'){if(!ownerDemo)return;const url=whatsappUrl(settings.whatsapp,'Hi Luxvibe, this is a demonstration enquiry — not a real order.');$('#test-link-result').innerHTML=`<div class="field" style="margin-top:20px"><label for="generated-link">Generated URL · not opened</label><textarea id="generated-link" readonly>${esc(url)}</textarea><small>Correctly URL-encoded official click-to-chat link. Real ordering remains disabled.</small></div>`;}
else if(action==='clear-data')showModal('Reset this demonstration?',`<p>This removes this prototype’s bag, wishlist, local product edits, settings and sample enquiries from this browser.</p><div class="dialog-actions"><button class="btn" data-action="reset-confirm">Reset demo data</button><button class="btn outline" data-action="close">Keep my changes</button></div>`);
else if(action==='reset-confirm'){for(const key of ['cart','wishlist','products','settings','enquiries']){try{localStorage.removeItem('luxvibe.'+key);}catch{}}try{sessionStorage.removeItem('luxvibe.owner');}catch{}location.hash='/';location.reload();}
else if(action==='export'){const blob=new Blob([JSON.stringify({demo:true,note:'Browser-local concept data; not verified inventory or real orders',products,settings,enquiries},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Luxvibe-Demo-Data.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);}
}catch(error){toast(error.message||'Something went wrong. Please try again.');}}
async function handleSubmit(e){const form=e.target;if(!['settings-form','content-form','product-form','enquiry-form'].includes(form.id))return;e.preventDefault();if(!ownerDemo)return;const data=new FormData(form);const error=$('.form-error',form);if(error)error.textContent='';try{
if(form.id==='settings-form'){const number=String(data.get('whatsapp')).trim();if(number)whatsappUrl(number,'Test');const url=new URL(data.get('instagram'));if(url.protocol!=='https:'||!['instagram.com','www.instagram.com'].includes(url.hostname))throw new Error('Use a valid HTTPS Instagram profile URL.');settings={...settings,whatsapp:number,instagram:url.href};const saved=persist('settings',settings);toast(saved?'Settings saved in this browser.':'Settings apply for this visit only. Browser storage is unavailable.');}
else if(form.id==='content-form'){const next={...settings};for(const [key,value] of data.entries())next[key]=String(value).trim();settings=next;const saved=persist('settings',settings);toast(saved?'Content saved in this browser.':'Content applies for this visit only. Browser storage is unavailable.');}
else if(form.id==='product-form'){const variants=String(data.get('variants')).trim().split('\n').map(line=>{const split=line.lastIndexOf(':');if(split<1)throw new Error('Use option:stock for each option.');return {name:line.slice(0,split).trim(),stock:Number(line.slice(split+1))};});if(new Set(variants.map(v=>v.name)).size!==variants.length)throw new Error('Option names must be unique.');const chosen=data.get('image');const newImage=chosen==='current'?uploadedImage:chosen;const slug=String(data.get('name')).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'sample-product';let newId=slug;if(!editingProduct&&products.some(p=>p.id===newId))newId+='-'+Date.now().toString(36);const next={id:editingProduct?.id||newId,name:String(data.get('name')).trim(),category:String(data.get('category')),price:Number(data.get('price')),colour:String(data.get('colour')).trim(),hex:String(data.get('hex')),image:newImage,description:String(data.get('description')).trim(),spec:String(data.get('spec')).trim(),variants,featured:data.has('featured'),archived:data.has('archived'),created:editingProduct?.created||Date.now()};validateProduct(next);products=editingProduct?products.map(p=>p.id===editingProduct.id?next:p):[...products,next];const saved=persist('products',products);saveCart();closeModal();render();toast(saved?'Sample product saved in this browser.':'Product applies for this visit only. Browser storage is unavailable.');}
else if(form.id==='enquiry-form'){enquiries=[...enquiries,{id:'demo-'+Date.now(),label:String(data.get('label')).trim(),product:String(data.get('product')),status:'New'}];persist('enquiries',enquiries);render();toast('Sample enquiry recorded locally.');}
}catch(err){if(error)error.textContent=err.message;else toast(err.message);}}
document.addEventListener('click',onAction);document.addEventListener('submit',handleSubmit);
document.addEventListener('input',e=>{if(e.target.id==='live-search')updateSearch(e.target.value);if(e.target.dataset.filter==='query'){filters.query=e.target.value;updateCollection();}});
document.addEventListener('change',async e=>{const f=e.target;if(f.dataset.filter&&f.dataset.filter!=='query'){filters[f.dataset.filter]=f.type==='checkbox'?f.checked:f.value;updateCollection();}if(f.dataset.enquiry){const entry=enquiries.find(x=>x.id===f.dataset.enquiry);if(entry&&['New','Discussing','Closed'].includes(f.value)){entry.status=f.value;persist('enquiries',enquiries);toast('Sample status updated.');}}if(f.id==='product-upload'){const file=f.files[0];if(!file)return;const error=$('#product-form .form-error');try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>600*1024)throw new Error('Choose a JPEG, PNG or WebP image no larger than 600 KB.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(new Error('The image file could not be decoded.'));img.src=data;});if(img.width>6000||img.height>6000)throw new Error('Image dimensions must be no larger than 6000 pixels per side.');uploadedImage=data;$('#product-image').value='current';error.textContent='';toast('Sample image ready. Save the product to keep it.');}catch(err){f.value='';error.textContent=err.message;}}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='live-search'){e.preventDefault();location.hash='/search?q='+encodeURIComponent(e.target.value);}if(e.key==='Escape')closeModal();});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#/"]');if(a&&modal.open)closeModal();});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&!e.target.dataset.fallback){e.target.dataset.fallback='yes';e.target.removeAttribute('srcset');e.target.src=ASSETS+'image-fallback.svg';}},true);
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});});
if(window.visualViewport){const adjust=()=>{const keyboard=window.innerHeight-window.visualViewport.height>150;const nav=$('.bottom-nav');if(nav)nav.style.visibility=keyboard?'hidden':'';};window.visualViewport.addEventListener('resize',adjust);}
render();
